readOnlyCommand:
$ErrorActionPreference='Stop'
$taskRoot=(Get-Location).Path
$step='analyse/ux-step5-2-2026-10-18/'
$issues=[System.Collections.Generic.List[string]]::new()
function Check-Pins($pins,$base,$label){
 foreach($pin in $pins){
  $file=[IO.Path]::GetFullPath((Join-Path $base $pin.path))
  if(!$file.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Pin escaped reviewed root'}
  if(!(Test-Path -LiteralPath $file -PathType Leaf)){$issues.Add($label+':missing:'+ $pin.path);continue}
  if((Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash -ine $pin.sha256){$issues.Add($label+':hash:'+ $pin.path)}
  if($null -ne $pin.bytes -and (Get-Item -LiteralPath $file).Length -ne $pin.bytes){$issues.Add($label+':bytes:'+ $pin.path)}
 }
}
$freeze=Get-Content -LiteralPath ($step+'FINAL-EVIDENCE-FREEZE.json') -Raw | ConvertFrom-Json
$freezeSha=(Get-FileHash -LiteralPath ($step+'FINAL-EVIDENCE-FREEZE.json') -Algorithm SHA256).Hash.ToLowerInvariant()
if($freezeSha -cne '80cb5e10adb4701135034aff4dbb120e4a1796ee0b24a97a3fd2297b2dcc6410'){throw 'Freeze identity mismatch'}
if($freeze.gateAndDeliverablePins.Count -ne 9 -or $freeze.selectedCanonicalPins.Count -ne 17 -or $freeze.referencedDraftMediaPins.Count -ne 55){throw 'Unexpected freeze denominators'}
Check-Pins $freeze.gateAndDeliverablePins $taskRoot 'consumer52'
Check-Pins $freeze.selectedCanonicalPins $taskRoot 'canonical52'
Check-Pins $freeze.referencedDraftMediaPins $taskRoot 'media52'
Check-Pins @($freeze.priorAppSourceFreeze,$freeze.prior51Freeze) $taskRoot 'prior-freeze'
$app=Get-Content -LiteralPath $freeze.priorAppSourceFreeze.path -Raw | ConvertFrom-Json
if($app.appInputs.Count -ne 237){throw 'Unexpected47 denominator'}
Check-Pins $app.appInputs (Resolve-Path -LiteralPath $app.candidate).Path 'approved47'
$prior=Get-Content -LiteralPath $freeze.prior51Freeze.path -Raw | ConvertFrom-Json
if($prior.consumerDocPins.Count -ne 7){throw 'Unexpected51 doc denominator'}
Check-Pins $prior.consumerDocPins $taskRoot 'approved51-docs'
$snapshot=Get-Content -LiteralPath ($step+'REVIEW-SNAPSHOT.json') -Raw | ConvertFrom-Json
$inventory=Get-Content -LiteralPath 'content/yoga-library/inventory.json' -Raw | ConvertFrom-Json
if($snapshot.sourceRecords.Count -ne 38 -or $snapshot.units.Count -ne 14 -or $snapshot.media.Count -ne 80){throw 'Unexpected snapshot counts'}
foreach($source in $snapshot.sourceRecords){
 $match=@($inventory.records | Where-Object {$_.courseId -ceq $source.courseId -and $_.id -ceq $source.lessonId -and $_.youtubeId -ceq $source.youtubeId})
 if($match.Count -ne 1){throw 'Source triple mismatch'}
 if(($match[0].contentUnitIds -join '|') -cne ($source.linkedUnitIds -join '|') -or $match[0].rightsStatus -cne $source.rightsStatus -or $match[0].expertStatus -cne $source.expertStatus -or $match[0].channelCaptionsVerified -ne $source.captionsVerified){throw 'Source metadata mismatch'}
}
$joins=0;$slots=0;$present=0;$blocked=0
foreach($entry in $snapshot.units){
 $unit=Get-Content -LiteralPath $entry.path -Raw | ConvertFrom-Json
 foreach($key in @('id','revision','locale','kind','productionStatus','publishStatus')){if($unit.$key -cne $entry.$key){throw ('Unit field mismatch:'+ $key)}}
 if($unit.learnerVisible -ne $false -or $unit.recommendationEligible -ne $false -or $null -ne $unit.practiceDurationSeconds -or $unit.review.approvalRecords.Count -ne 0){throw 'Unexpected unit publication/approval state'}
 foreach($review in @('expert','rights','editorial','accessibility')){if($unit.review.$review -cne 'pending'){throw 'Unexpected review state'}}
 foreach($ref in $unit.sourceRefs){$match=@($inventory.records | Where-Object {$_.courseId -ceq $ref.courseId -and $_.id -ceq $ref.lessonId -and $_.youtubeId -ceq $ref.youtubeId});if($match.Count -ne 1 -or $match[0].contentUnitIds -notcontains $unit.id -or $ref.contentObserved -ne $false){throw 'Source relation mismatch'};$joins++}
 foreach($asset in $unit.media){
  $match=@($snapshot.media | Where-Object {$_.unitId -ceq $unit.id -and $_.revision -ceq $unit.revision -and $_.locale -ceq $unit.locale -and $_.mediaId -ceq $asset.id})
  if($match.Count -ne 1 -or $match[0].status -cne $asset.status -or $match[0].stepId -cne $asset.stepId -or $match[0].declaredSha256 -cne $asset.sha256){throw 'Media identity/status mismatch'}
  if($asset.status -ceq 'draft_present'){if($match[0].path -cne ('content/yoga-library/'+$asset.path) -or $match[0].fileExists -ne $true -or $match[0].declaredHashMatches -ne $true){throw 'Present media mismatch'};$present++}
  elseif($asset.status -ceq 'identity_blocked'){if($null -ne $asset.path -or $null -ne $asset.sha256 -or $null -ne $match[0].path -or $match[0].fileExists -ne $false){throw 'Blocked media mismatch'};$blocked++}
  else{throw 'Unexpected media state'}
  $slots++
 }
}
if($joins -ne 13 -or $slots -ne 80 -or $present -ne 55 -or $blocked -ne 25){throw 'Snapshot total mismatch'}
if($snapshot.humanSelection -cne 'OWNER_REPORTED_SELECTED_DETAILS_PENDING' -or $snapshot.humanReview -cne 'BLOCKED_DETAILS_AND_EVIDENCE_PENDING'){throw 'Human state mismatch'}
$links=0
foreach($pin in $freeze.gateAndDeliverablePins | Where-Object {$_.path.EndsWith('.md')}){
 $body=Get-Content -LiteralPath $pin.path -Raw
 foreach($match in [regex]::Matches($body,'\[[^\]]+\]\(([^)]+)\)')){
  $target=$match.Groups[1].Value
  if($target -match '^(https?://|#)'){continue}
  $links++
  $file=[IO.Path]::GetFullPath((Join-Path (Split-Path -Parent (Join-Path $taskRoot $pin.path)) $target.Split('#')[0]))
  if(!(Test-Path -LiteralPath $file)){$issues.Add('link:'+ $target)}
 }
}
$qcSha=(Get-FileHash -LiteralPath ($step+'FINAL-QC.vi.md') -Algorithm SHA256).Hash.ToLowerInvariant()
$qcEvidenceSha=(Get-FileHash -LiteralPath ($step+'FINAL-QC-CHECK.json') -Algorithm SHA256).Hash.ToLowerInvariant()
if($qcSha -cne '9a81da0b068da95ada20e3512a79265c6a9ae4d3a9f80a4ebff5718059d9683f' -or $qcEvidenceSha -cne 'b16f808c2e0e8e4683faf07468d968b44917cc22ac9d0dbf4fa45d9d7ba6fa6c'){throw 'Independent QC identity mismatch'}
$dirty=@(git -c core.quotepath=false diff --name-only 2>$null)
$dirtyPins=@(foreach($file in $dirty){[pscustomobject]@{path=$file;sha256=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash.ToLowerInvariant()}})
[pscustomobject]@{observedAt=[DateTime]::UtcNow.ToString('o');status=if($issues.Count -eq 0){'PASS_ROOT_TECHNICAL_PACKET_ONLY'}else{'FAIL_ROOT_TECHNICAL_PACKET'};freezeSha256=$freezeSha;qcSha256=$qcSha;qcEvidenceSha256=$qcEvidenceSha;counts=[pscustomobject]@{consumerDocs=9;canonicalMetadata=17;referencedMedia=55;approved47Inputs=237;prior51ConsumerDocs=7;sourceRecords=38;unitVersions=14;sourceJoins=$joins;mediaSlots=$slots;draftPresent=$present;identityBlocked=$blocked;notProduced=0;localLinkOccurrences=$links};humanSelection=$snapshot.humanSelection;humanReview=$snapshot.humanReview;upstreamManifestCurrentlyPresent=(Test-Path -LiteralPath 'content/yoga-library/manifest.json');expansionDirectoryCurrentlyPresent=(Test-Path -LiteralPath 'content/yoga-library/expansion');issues=@($issues);rootTrackedDirtyPins=$dirtyPins} | ConvertTo-Json -Depth 6
if($issues.Count -gt 0){exit 1}
